def fill_receipts(apps, schema_editor):
    Application = apps.get_model('accounts', 'MembershipApplication')
    for item in Application.objects.all().iterator():
        item.tracking_token = uuid.uuid4()
        item.save(update_fields=['tracking_token'])


def seed_contributors(apps, schema_editor):
    Contributor = apps.get_model('accounts', 'Contributor')
    Credit = apps.get_model('accounts', 'PostCredit')
    Post = apps.get_model('alpha', 'LandingContent')
    Group = apps.get_model('auth', 'Group')
    Permission = apps.get_model('auth', 'Permission')
    ContentType = apps.get_model('contenttypes', 'ContentType')
    for name, role in [('Ashish Maurya', 'Developer'), ('Rudransh Shukla', 'Developer'), ('Ishita', 'Writer'), ('Johanna Huber', 'Writer'), ('Ruby', 'Writer'), ('Sanja', 'Writer'), ('Selina', 'Writer'), ('Sophia', 'Writer')]:
        Contributor.objects.get_or_create(name=name, defaults={'role': role})
    for post in Post.objects.exclude(author='').iterator():
        for name in post.author.split(' and '):
            person, _ = Contributor.objects.get_or_create(name=name.strip())
            Credit.objects.get_or_create(post=post, contributor=person)
    core, _ = Group.objects.get_or_create(name='core_team_admin')
    for model, code, label in [('profile', 'change_other_profiles', 'Edit other member profiles'), ('profile', 'access_team_workspace', 'Access team workspace'), ('auditlog', 'manage_roles', 'Manage team roles'), ('auditlog', 'view_auditlog', 'View audit log'), ('membershipapplication', 'review_applications', 'Review membership applications')]:
        content_type, _ = ContentType.objects.get_or_create(app_label='accounts', model=model)
        permission, _ = Permission.objects.get_or_create(content_type=content_type, codename=code, defaults={'name': label})
        core.permissions.add(permission)
    # No users are granted this new role automatically.


